                target=target,
                status="SENT",
                now=now,
                resolved_channel="dws_group_chat",
                group_conversation_id=conversation_id,
                reports=reports,
            )
        last_error = str(result.get("failure_reason") or result.get("errmsg") or "dws group send failed")
    else:
